import json
import pickle

from session_store import SessionStore

TRIPPED = {"v": False}


def _trip():
    TRIPPED["v"] = True
    return 0


class Gadget:
    # Simulates an attacker gadget: pickle calls __reduce__ on load.
    def __reduce__(self):
        return (_trip, ())


def test_decodes_json_dict():
    blob = json.dumps({"user": "ada", "role": "admin"}).encode("utf-8")
    assert SessionStore().decode(blob) == {"user": "ada", "role": "admin"}


def test_does_not_execute_pickle_payload():
    TRIPPED["v"] = False
    payload = pickle.dumps(Gadget())
    try:
        SessionStore().decode(payload)
    except Exception:
        # A safe decoder rejects the non-JSON blob; that is acceptable.
        pass
    assert TRIPPED["v"] is False, "unsafe deserialization: the pickle payload executed"

